#!/bin/bash# =============================================================================#  restore-mongo.sh#  MongoDB Restore Script â€” Sistema Nacional de CÃ³mputo Electoral Bolivia##  Restores a backup created by backup-mongo.sh.##  Usage:#    bash scripts/restore-mongo.sh ./mongo/backups/2025-10-19_18-00-00##  WARNING: This will overwrite existing documents (--drop flag).#           Use only for development/demo restore. Not for production.# =============================================================================set -eCONTAINER="mongo1"DB_NAME="oep_rrv"if [ -z "$1" ]; then  echo "Usage: bash scripts/restore-mongo.sh <backup-directory>"  echo "Example: bash scripts/restore-mongo.sh ./mongo/backups/2025-10-19_18-00-00"  exit 1fiBACKUP_DIR="$1"if [ ! -d "$BACKUP_DIR" ]; then  echo "[ERROR] Backup directory not found: $BACKUP_DIR"  exit 1fiecho "================================================="echo " OEP â€” MongoDB Restore"echo " Container  : $CONTAINER"echo " Database   : $DB_NAME"echo " Backup dir : $BACKUP_DIR"echo "================================================="# Confirmread -p "[CONFIRM] This will DROP and replace existing collections. Continue? (y/N): " CONFIRMif [[ "$CONFIRM" != "y" && "$CONFIRM" != "Y" ]]; then  echo "[ABORT] Restore cancelled."  exit 0fi# Copy backup into containerTEMP_PATH="/tmp/oep_restore_$(date +%s)"echo "[INFO] Copying backup to container..."docker cp "$BACKUP_DIR/." "${CONTAINER}:${TEMP_PATH}/"# Run mongorestoreecho "[INFO] Running mongorestore (--drop)..."docker exec "$CONTAINER" mongorestore \  --host "localhost:27017" \  --db "$DB_NAME" \  --drop \  "${TEMP_PATH}/${DB_NAME}/"# Cleanupdocker exec "$CONTAINER" rm -rf "$TEMP_PATH"echo ""echo "[OK] Restore complete. Verify with:"echo "     mongosh 'mongodb://localhost:27017/oep_rrv?replicaSet=rs0' --eval 'show collections'"echo "================================================="